    if(!sceneIsCurrent(version))return false;
    if(!ready){console.warn(`BLACKOUT: artwork not ready for ${key}; the current screen is retained.`);setTimeout(()=>{if(sceneIsCurrent(version))enterPreparedSection(key,render);},1000);return false;}
