function showPhoneBriefing(){if(!sectionIsReady('phone'))return enterPreparedSection('phone',showPhoneBriefing);const hudImage=hud.querySelector(':scope > img');if(!hudImage.getAttribute('src'))hudImage.src=ASSETS.hud;clearScreen();hud.classList.remove('hidden');screen.style.backgroundImage=`linear-gradient(#01050bcf,#01050be8),url('${ASSETS.home}')`;const ready=preloadFirstQuestionPanel();const stage=document.createElement('section');stage.className='phone-briefing';stage.innerHTML='<h2>EMERGENCY BROADCAST RECEIVED</h2><p>CITYWIDE BLACKOUT CONFIRMED</p><strong>Reach the riverside evacuation point.</strong>';screen.append(stage);transitionId=sceneTimeout(async()=>{const version=sceneVersion;await ready;if(!sceneIsCurrent(version))return;state.game=1;state.questionIndex=0;state.gameProgress=0;showQuestion();},READABLE_MESSAGE_DURATION);}
function currentGrammarData(){return state.game===5?ERROR_DETECTOR_DATA:state.game===4?SIGNAL_SCANNER_DATA:state.game===3?SUPPLY_SEARCH_DATA:state.game===2?STREET_SIGNALS_DATA:GRAMMAR_DATA;}
function showQuestion(){const readinessKey=state.game===3?'game3':state.game===4?'game4':'game1';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showQuestion);if(state.game===4){showTunnelDrive();return;}if(state.game===3){showSupplySearchScene();return;}if(state.game===2){showStreetGridQuestion();return;}locked=false;state.lives=3;updateHud();clearScreen();const questions=currentGrammarData(),question=questions[state.questionIndex];const stage=document.createElement('div');stage.className='question-stage';const panel=document.createElement('div');panel.className='question-panel';const copy=document.createElement('div');copy.className='question-copy';copy.innerHTML='<p class="eyebrow">GAME 1 — EMERGENCY PHONE</p><p class="instruction">Choose the correct answer.</p><p class="sentence"></p>';copy.querySelector('.sentence').textContent=question.sentence||'';const answers=document.createElement('div');answers.className='answers';question.options.forEach(option=>{const answer=document.createElement('button');const answerCopy=document.createElement('span');answer.className='answer';answerCopy.className='answer-copy';answerCopy.textContent=option;answer.append(answerCopy);answer.setAttribute('aria-label',option);answer.onclick=()=>answerQuestion(answer,option);answers.append(answer);});panel.append(copy,answers);stage.append(panel);screen.append(stage);if(state.energy===0)showEnergyRecovery();}
const renderHomeWithoutHud=showHome;showHome=function(){hud.classList.add('hidden');renderHomeWithoutHud();};
const renderQuestionWithHud=showQuestion;showQuestion=function(){hud.classList.remove('hidden');renderQuestionWithHud();};
function createStreetGrid(poweredCount=state.gameProgress){const grid=document.createElement('div');grid.className='street-power-grid';grid.innerHTML=`<img src="${ASSETS.streetPowerGrid}" alt="Street power network"><div class="street-grid-nodes" aria-hidden="true"></div>`;const nodes=grid.querySelector('.street-grid-nodes');for(let index=0;index<4;index++){const node=document.createElement('i');node.className=`street-grid-node node-${index+1}${index<poweredCount?' powered':''}`;nodes.append(node);}return grid;}
function showStreetGridQuestion(){const readinessKey='game2';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showStreetGridQuestion);locked=false;state.lives=3;updateHud();clearScreen();const question=STREET_SIGNALS_DATA[state.questionIndex],stage=document.createElement('div');stage.className='street-grid-stage';stage.style.backgroundImage=`linear-gradient(#030912b8,#070404c4),url('${ASSETS.blackoutStreet}')`;stage.innerHTML=`<header class="street-grid-question"><p>GAME 2 — STREET SIGNALS</p><strong>RESTORE THE STREET GRID</strong><span></span></header><output class="street-grid-progress">GRID POWER ${state.gameProgress*25}%</output>`;stage.querySelector('.street-grid-question span').textContent=question.sentence;const grid=createStreetGrid();const signals=document.createElement('div');signals.className='street-grid-signals';question.options.forEach((option,index)=>{const signal=document.createElement('button');signal.type='button';signal.className=`street-signal signal-${index+1}`;signal.textContent=option;signal.setAttribute('aria-label',option);signal.onclick=()=>answerStreetSignal(stage,signal,option);signals.append(signal);});stage.append(grid,signals);addNightfallCollectible(stage,'usb');screen.append(stage);if(state.energy===0)showEnergyRecovery();}
function answerStreetSignal(stage,signal,choice){if(locked)return;const question=STREET_SIGNALS_DATA[state.questionIndex];if(choice===question.answer){locked=true;stage.querySelectorAll('.street-signal').forEach(item=>item.disabled=true);signal.classList.add('correct');state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;const node=stage.querySelector(`.node-${state.gameProgress}`),stageRect=stage.getBoundingClientRect(),signalRect=signal.getBoundingClientRect(),nodeRect=node.getBoundingClientRect(),pulse=document.createElement('i');pulse.className='street-travel-pulse';pulse.style.left=`${signalRect.left-stageRect.left+signalRect.width/2}px`;pulse.style.top=`${signalRect.top-stageRect.top+signalRect.height/2}px`;pulse.style.setProperty('--travel-x',`${nodeRect.left-signalRect.left+(nodeRect.width-signalRect.width)/2}px`);pulse.style.setProperty('--travel-y',`${nodeRect.top-signalRect.top+(nodeRect.height-signalRect.height)/2}px`);stage.append(pulse);sceneTimeout(()=>{node.classList.add('powered','powering');stage.querySelector('.street-grid-progress').textContent=`GRID POWER ${state.gameProgress*25}%`;},720);audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=sceneTimeout(nextQuestion,1500);return;}signal.classList.add('wrong');sceneTimeout(()=>signal.classList.remove('wrong'),500);audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;stage.querySelectorAll('.street-signal').forEach(item=>item.disabled=true);transitionId=sceneTimeout(launchEmergencyRescue,750);}}
function answerQuestion(buttonElement,choice){if(locked)return;const question=currentGrammarData()[state.questionIndex];if(choice===question.answer){locked=true;buttonElement.classList.add('correct');document.querySelectorAll('.answer').forEach(answer=>answer.disabled=true);state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;if(state.game===2||state.game===4)state.gameProgress++;audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=sceneTimeout(nextQuestion,1500);return;}buttonElement.classList.add('wrong');sceneTimeout(()=>buttonElement.classList.remove('wrong'),500);audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;document.querySelectorAll('.answer').forEach(answer=>answer.disabled=true);transitionId=sceneTimeout(launchEmergencyRescue,750);}}
function nextQuestion(){state.questionIndex++;if(state.game===2?state.questionIndex<4:state.questionIndex<currentGrammarData().length)showQuestion();else if(state.game===1)showGameOneComplete();else if(state.game===2)showGameTwoComplete();else showServiceTunnelsComplete();}
function showGameOneComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.home}')`;const gameTwoReady=preloadImages([ASSETS.blackoutStreet,ASSETS.streetPowerGrid,NIGHTFALL_COLLECTIBLES.usb.asset]);const success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>EVACUATION ROUTE RECEIVED ✓</h2>';screen.append(success);transitionId=sceneTimeout(()=>completeEnergyStep(1,async()=>{const version=sceneVersion;await gameTwoReady;if(!sceneIsCurrent(version))return;showBlackoutStreet();}),SHORT_STATUS_DURATION);}
