function showGameTwoComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.blackoutStreet}')`;const ready=preloadImages([ASSETS.supermarketExteriorBlackout,ASSETS.supermarketInterior,ASSETS.typing,...SUPPLY_SEARCH_DATA.map(item=>item.asset)]),version=sceneVersion;const success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>STREET POWER RESTORED ✓</h2>';screen.append(success);transitionId=sceneTimeout(()=>completeEnergyStep(2,async()=>{const version=sceneVersion;await ready;if(sceneIsCurrent(version))showSupplySearchIntro();}),SHORT_STATUS_DURATION);}
