function normalizeTypedAnswer(value){return value.trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ');}
function showSupplySearchScene(){const readinessKey='game3';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showSupplySearchScene);locked=false;state.lives=3;updateHud();clearScreen();const question=SUPPLY_SEARCH_DATA[state.questionIndex],stage=document.createElement('div');stage.className='supply-search-stage flashlight-active';stage.style.backgroundImage=`url('${ASSETS.supermarketInterior}')`;stage.innerHTML='<div class="supply-darkness" aria-hidden="true"></div><div class="supply-beam" aria-hidden="true"></div><header class="supply-search-instruction"><strong>SUPPLY SEARCH</strong><span>Use your flashlight to find 4 supplies:<br>Water • First Aid Kit • Chocolate • Batteries</span><b></b></header>';screen.append(stage);activateSupplyFlashlight(stage,question);if(state.energy===0)showEnergyRecovery();}
function activateSupplyFlashlight(stage,question){const instruction=stage.querySelector('.supply-search-instruction'),searchNames=['WATER','FIRST AID KIT','CHOCOLATE','BATTERIES'],target=document.createElement('button');instruction.querySelector('b').textContent=`CURRENT TARGET: ${searchNames[state.questionIndex]}`;target.type='button';target.className=`supply-search-target supply-target-${state.questionIndex+1}`;target.setAttribute('aria-label',`Find ${question.reward}`);target.innerHTML=`<img src="${question.asset}" alt="${question.reward}">`;target.onclick=()=>{if(locked)return;locked=true;target.classList.add('found');audio.sfx('select');transitionId=sceneTimeout(()=>showTypingQuestion(stage),420);};stage.append(target);let targetX=50,targetY=42,currentX=50,currentY=42;stage.onpointermove=event=>{const bounds=stage.getBoundingClientRect();targetX=Math.max(2,Math.min(98,(event.clientX-bounds.left)/bounds.width*100));targetY=Math.max(25,Math.min(96,(event.clientY-bounds.top)/bounds.height*100));};let beamFrame=0;const beamObserver=new MutationObserver(()=>{if(!stage.isConnected){cancelAnimationFrame(beamFrame);beamFrame=0;beamObserver.disconnect();return;}if(stage.classList.contains('search-paused')){cancelAnimationFrame(beamFrame);beamFrame=0;}else if(!beamFrame)beamFrame=requestAnimationFrame(followBeam);});beamObserver.observe(stage,{attributes:true,attributeFilter:['class']});beamObserver.observe(screen,{childList:true});const followBeam=()=>{beamFrame=0;if(!stage.isConnected){beamObserver.disconnect();return;}if(stage.classList.contains('search-paused'))return;currentX+=(targetX-currentX)*.14;currentY+=(targetY-currentY)*.14;stage.style.setProperty('--beam-x',`${currentX}%`);stage.style.setProperty('--beam-y',`${currentY}%`);const bounds=stage.getBoundingClientRect(),targetBounds=target.getBoundingClientRect(),targetCenterX=targetBounds.left+targetBounds.width/2,targetCenterY=targetBounds.top+targetBounds.height/2,cursorX=bounds.left+currentX/100*bounds.width,cursorY=bounds.top+currentY/100*bounds.height;target.classList.toggle('illuminated',Math.hypot(targetCenterX-cursorX,targetCenterY-cursorY)<bounds.width*.18);beamFrame=requestAnimationFrame(followBeam);};beamFrame=requestAnimationFrame(followBeam);}
function showTypingQuestion(stage=screen.querySelector('.supply-search-stage')){locked=false;const question=SUPPLY_SEARCH_DATA[state.questionIndex];stage.classList.add('search-paused');const overlay=document.createElement('div');overlay.className='supply-grammar-overlay';const panel=document.createElement('div');panel.className='typing-panel';const copy=document.createElement('div');copy.className='typing-panel-copy';copy.innerHTML='<p class="eyebrow">GAME 3 — SUPPLY SEARCH</p><p class="instruction">Type the correct verb form.</p><p class="sentence"></p>';copy.querySelector('.sentence').textContent=question.sentence;const controls=document.createElement('form');controls.className='typing-panel-controls';controls.innerHTML='<input class="typing-input" type="text" placeholder="Type your answer here..." autocomplete="off" aria-label="Type the correct verb form"><button type="submit" aria-label="Submit answer"></button>';controls.onsubmit=event=>{event.preventDefault();submitTypedAnswer(controls.querySelector('.typing-input'));};panel.append(copy,controls);overlay.append(panel);stage.append(overlay);controls.querySelector('.typing-input').focus();}
function submitTypedAnswer(input){if(locked)return;const question=SUPPLY_SEARCH_DATA[state.questionIndex];if(normalizeTypedAnswer(input.value)===normalizeTypedAnswer(question.answer)){locked=true;input.disabled=true;input.form.querySelector('button').disabled=true;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=sceneTimeout(()=>awardSupplyItem(question),650);return;}input.classList.remove('wrong');void input.offsetWidth;input.classList.add('wrong');audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;input.disabled=true;input.form.querySelector('button').disabled=true;transitionId=sceneTimeout(launchEmergencyRescue,750);return;}input.focus();input.select();}
function awardSupplyItem(question){if(state.inventory.includes(question.reward)){advanceSupplySearch();return;}audio.sfx('itemPickup');const reward=document.createElement('div');reward.className='item-found';reward.innerHTML=`<div class="reward-card"><p>SUPPLY ACQUIRED</p><img src="${question.asset}" alt="${question.reward}"><strong>${question.reward.toUpperCase()}</strong></div>`;screen.append(reward);const item=reward.querySelector('img');transitionId=sceneTimeout(()=>{state.inventory.push(question.reward);const itemBox=item.getBoundingClientRect(),backpackBox=document.querySelector('.backpack-icon').getBoundingClientRect();item.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${backpackBox.left+backpackBox.width/2-itemBox.left-itemBox.width/2}px,${backpackBox.top+backpackBox.height/2-itemBox.top-itemBox.height/2}px) scale(.12)`,opacity:0}],{duration:900,easing:'ease-in',fill:'forwards'}).finished.then(()=>{if(!reward.isConnected)return;updateHud();document.querySelector('#backpack').classList.add('collect-pulse');sceneTimeout(()=>document.querySelector('#backpack').classList.remove('collect-pulse'),650);advanceSupplySearch();});},2000);}
function advanceSupplySearch(){state.questionIndex++;if(state.questionIndex<SUPPLY_SEARCH_DATA.length)showQuestion();else showGameThreeComplete();}
function showGameThreeComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.supermarketExteriorBlackout}')`;const routesReady=preloadImages([ASSETS.routeSelection,ASSETS.serviceTunnels,ASSETS.tunnelRoutes,ASSETS.interactive.car,NIGHTFALL_COLLECTIBLES.processor.asset]),success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>SUPPLIES SECURED ✓</h2>';screen.append(success);transitionId=sceneTimeout(()=>completeEnergyStep(3,async()=>{const version=sceneVersion;await routesReady;if(!sceneIsCurrent(version))return;showRouteSelection();}),SHORT_STATUS_DURATION);}
// Rescue Zone encompasses Games 7–10; its map completion must never bypass the checkpoint.
function routeMilestoneCount(){return state.evacuationPointCompleted?5:state.rescueZoneCompleted?4:state.mainBridgeCompleted?3:state.cityStreetsCompleted?2:state.serviceTunnelsCompleted?1:0;}
function showRouteSelection(){const readinessKey='route';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showRouteSelection);clearScreen();hud.classList.add('hidden');const completed=routeMilestoneCount(),labels=['HOME','SERVICE TUNNELS','CITY CENTER','MAIN BRIDGE','RESCUE ZONE','EVACUATION POINT'],composition=artComposition(ASSETS.routeSelection,'Evacuation route progress');composition.classList.add('progress-map');composition.dataset.routeState=String(completed+1);const nodes=document.createElement('div');nodes.className='map-milestones';nodes.setAttribute('role','list');nodes.setAttribute('aria-label','Route milestones');labels.forEach((label,index)=>{const status=index<=completed?'completed':index===completed+1?'current':'future',node=document.createElement('div');node.className=`map-milestone ${status}`;node.setAttribute('role','listitem');node.setAttribute('aria-label',`${label}: ${status==='current'?'next destination':status}`);node.style.setProperty('--node-x',`${[9.2,25.5,41.7,58.2,74.5,90.9][index]}%`);node.style.setProperty('--trail-x',`${[12,26,41.3,55.9,71.7,89.1][index]}%`);node.style.setProperty('--trail-y',`${index===0?77.9:78.6}%`);node.innerHTML=`<span class="map-node-ring"></span><span class="map-node-label">${label}</span><span class="map-node-badge">${status==='completed'?'✓':status==='current'?'NEXT':''}</span><span class="map-trail-node">${status==='completed'?'✓':index}</span>`;nodes.append(node);});const progress=document.createElement('p');progress.className='map-progress';progress.textContent=completed===5?'ALL ROUTE MILESTONES COMPLETE':`NEXT: ${labels[completed+1]}`;const go=button('map-continue','Continue to the next sector');go.textContent='CONTINUE';go.onclick=()=>{if(go.disabled)return;go.disabled=true;audio.sfx('select');hud.classList.remove('hidden');if(completed===0)showServiceTunnelsIntro();else if(completed===1)showCityStreetsIntro();else if(completed===2)showMainBridgeIntro();else if(completed===3){state.game=7;state.questionIndex=0;state.gameProgress=0;showRooftopSignalQuestion();}else if(completed===4)showGameTwelveLocked();else showFinalAuthorization();};composition.append(nodes,progress,go);screen.append(composition);}

