function shuffleSignalTunnels(options,previous=''){let shuffled,key;do{shuffled=[...options];for(let index=shuffled.length-1;index>0;index--){const swap=Math.floor(Math.random()*(index+1));[shuffled[index],shuffled[swap]]=[shuffled[swap],shuffled[index]];}key=shuffled.join('|');}while(key===previous&&shuffled.length>1);return shuffled;}
