function showEmergencyRadioTransmission(){const readinessKey='game9';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showEmergencyRadioTransmission);locked=false;state.lives=3;updateHud();clearScreen();const task=EMERGENCY_RADIO_DATA[state.questionIndex],stage=document.createElement('div');stage.className=`radio-game radio-${task.mode}`;stage.style.backgroundImage=`url('${ASSETS.railwayStation}')`;stage.innerHTML='<header class="radio-header"><p>GAME 9 — EMERGENCY RADIO</p><strong>Tune the radio and complete the missing part of each message.</strong><span></span></header><div class="radio-unit"><img alt="Emergency radio"><section class="radio-display" aria-live="polite"><div class="radio-wave" aria-hidden="true"></div><b>SIGNAL LOST</b><output class="radio-frequency"></output><div class="radio-strength"><i></i></div><div class="radio-controls"></div></section></div>';stage.querySelector('.radio-header span').textContent=`SIGNALS RESTORED ${state.gameProgress}/4`;stage.querySelector('.radio-unit img').src=ASSETS.interactive.emergencyRadio;stage.querySelector('.radio-frequency').textContent=task.frequency;const controls=stage.querySelector('.radio-controls');if(task.mode==='channels'){const channels=[...task.channels].sort(()=>Math.random()-.5);channels.forEach(frequency=>{const channel=document.createElement('button');channel.type='button';channel.textContent=frequency;channel.onclick=()=>{if(locked)return;if(frequency===task.frequency){revealRadioMessage(stage,task);return;}stage.querySelector('.radio-display b').textContent='NO SIGNAL';stage.querySelector('.radio-display').classList.remove('interference');void stage.querySelector('.radio-display').offsetWidth;stage.querySelector('.radio-display').classList.add('interference');};controls.append(channel);});}else{radioTarget=task.target;const slider=document.createElement('input');slider.type='range';slider.min='0';slider.max='100';slider.value=task.mode==='damaged'?'24':'18';slider.className='radio-tuner';slider.setAttribute('aria-label','Radio tuning');slider.oninput=()=>updateRadioTuning(slider,stage,task);controls.append(slider);if(task.mode==='drift'){const marker=document.createElement('i');marker.className='drift-marker';controls.append(marker);radioDriftId=setInterval(()=>{if(!document.body.contains(stage)||locked)return;radioTarget=50+Math.sin(Date.now()/1700)*12;marker.style.left=`${radioTarget}%`;updateRadioTuning(slider,stage,task);},120);}}screen.append(stage);if(state.energy===0)showEnergyRecovery();}
function updateRadioTuning(slider,stage,task){if(locked)return;const distance=Math.abs(Number(slider.value)-radioTarget),strength=Math.max(0,100-distance*2);stage.style.setProperty('--radio-strength',`${strength}%`);stage.querySelector('.radio-frequency').textContent=`${(86+Number(slider.value)*.24).toFixed(1)} FM`;stage.querySelector('.radio-display').classList.toggle('near',distance<18);const tolerance=task.mode==='damaged'?6:task.mode==='drift'?7:9;if(distance<=tolerance)revealRadioMessage(stage,task);}
function revealRadioMessage(stage,task){if(locked)return;locked=true;clearInterval(radioDriftId);radioDriftId=0;stage.style.setProperty('--radio-strength','100%');const display=stage.querySelector('.radio-display');display.classList.add('signal-found');display.querySelector('b').textContent='SIGNAL FOUND';display.querySelector('.radio-frequency').textContent=task.frequency;audio.sfx('select');transitionId=sceneTimeout(()=>showRadioGrammar(stage,task),450);}
function showRadioGrammar(stage,task){if(!document.body.contains(stage))return;locked=false;const display=stage.querySelector('.radio-display');display.replaceChildren();display.className='radio-display grammar-ready';const status=document.createElement('b');status.textContent='SIGNAL FOUND';const form=document.createElement('form');form.className='radio-message';const sentence=document.createElement('p');task.parts.forEach((part,index)=>{sentence.append(document.createTextNode(part));if(index<task.answers.length){const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=Math.max(7,task.answers[index].length+1);input.setAttribute('aria-label',`Missing part ${index+1}`);sentence.append(input);}});const submit=document.createElement('button');submit.type='submit';submit.textContent='TRANSMIT';form.append(sentence,submit);form.onsubmit=event=>{event.preventDefault();submitRadioAnswer(form,task);};display.append(status,form);form.querySelector('input').focus();}
function submitRadioAnswer(form,task){if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>normalizeTypedAnswer(input.value)===normalizeTypedAnswer(task.answers[index]));if(correct){locked=true;inputs.forEach(input=>{input.disabled=true;input.classList.add('correct');});form.querySelector('button').disabled=true;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;audio.sfx('correct');updateHud();form.closest('.radio-display').querySelector('b').textContent='SIGNAL LOCKED';showFeedback(`TRANSMISSION RESTORED ${state.gameProgress}/4`,'good',1450);transitionId=sceneTimeout(nextEmergencyRadioTransmission,1500);return;}inputs.forEach((input,index)=>input.classList.toggle('wrong',normalizeTypedAnswer(input.value)!==normalizeTypedAnswer(task.answers[index])));const display=form.closest('.radio-display');display.classList.remove('interference');void display.offsetWidth;display.classList.add('interference');audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'TRANSMISSION ERROR — EMERGENCY RESCUE':'TRANSMISSION ERROR','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;inputs.forEach(input=>input.disabled=true);form.querySelector('button').disabled=true;transitionId=sceneTimeout(launchEmergencyRescue,750);return;}const firstWrong=inputs.find(input=>input.classList.contains('wrong'));firstWrong?.focus();firstWrong?.select();}
function nextEmergencyRadioTransmission(){state.questionIndex++;if(state.questionIndex<EMERGENCY_RADIO_DATA.length)showEmergencyRadioTransmission();else showEmergencyRadioComplete();}
