function showGameTenLocked(){const readinessKey='checkpoint';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showGameTenLocked);clearScreen();screen.classList.add('scene-arrival');screen.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;screen.append(createMissionIntro('RESTORE THE CHECKPOINT','The rescue signal leads through a checkpoint linked to Project Nightfall.','CAMERA → GATE → BEACON → ACCESS'));transitionId=sceneTimeout(()=>{state.game=10;state.questionIndex=0;state.gameProgress=0;showCheckpointStage();},CITY_TRANSITION_MS);}
function showCheckpointStage(){const readinessKey='checkpoint';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showCheckpointStage);locked=false;state.lives=3;updateHud();clearScreen();const module=CHECKPOINT_DATA[state.questionIndex],stage=document.createElement('div');stage.className='checkpoint-game';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;stage.innerHTML='<header class="checkpoint-header"><p>GAME 10 — RESTORE THE CHECKPOINT</p><strong>Restore all four checkpoint systems.</strong><span></span></header><div class="checkpoint-board"><img alt="Checkpoint control panel"><div class="checkpoint-modules"></div><div class="checkpoint-statuses"></div></div><div class="checkpoint-object-zone"></div>';stage.querySelector('.checkpoint-header span').textContent=`SYSTEMS RESTORED: ${state.gameProgress}/4`;stage.querySelector('.checkpoint-board>img').src=ASSETS.interactive.checkpointPanel;const modules=stage.querySelector('.checkpoint-modules'),statuses=stage.querySelector('.checkpoint-statuses');CHECKPOINT_DATA.forEach((item,index)=>{const control=document.createElement('button');control.type='button';control.className=`checkpoint-module module-${index+1} ${index<state.gameProgress?'restored':index===state.questionIndex?'current':'locked'}`;control.disabled=index!==state.questionIndex;control.setAttribute('aria-label',`${item.name} ${index<state.gameProgress?'restored':index===state.questionIndex?'current':'locked'}`);modules.append(control);const status=document.createElement('span');status.className=`checkpoint-status status-${index+1} ${index<state.gameProgress?'online':''}`;status.textContent=index<state.gameProgress?item.status:index===state.questionIndex?'OFFLINE — REPAIR':'LOCKED';statuses.append(status);if(index===state.questionIndex){if(item.object){control.ondragover=event=>{if(!locked){event.preventDefault();event.dataTransfer.dropEffect='move';}};control.ondrop=event=>{event.preventDefault();if(locked||event.dataTransfer.getData('text/plain')!==item.object)return;activateCheckpointModule(stage,module);};}else control.onclick=()=>{if(!locked)activateCheckpointModule(stage,module);};}});const objectZone=stage.querySelector('.checkpoint-object-zone');if(module.object){const missionObject=document.createElement('img');missionObject.className=`checkpoint-object object-${module.object}`;missionObject.src=ASSETS.checkpointItems[module.object];missionObject.alt=module.object==='toolKit'?'Tool Kit':module.object==='accessCard'?'Emergency Access Card':'Batteries';missionObject.draggable=true;missionObject.ondragstart=event=>{if(locked){event.preventDefault();return;}event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',module.object);};objectZone.append(missionObject);}const instruction=document.createElement('strong');instruction.className='checkpoint-instruction';instruction.textContent=module.instruction;objectZone.append(instruction);addNightfallCollectible(stage,'core');screen.append(stage);if(state.energy===0)showEnergyRecovery();}
function beginCheckpointPointerDrag(event){const object=event.target.closest('.checkpoint-object');if(!object||state.game!==10||locked||event.button!==0)return;event.preventDefault();const stage=object.closest('.checkpoint-game'),target=stage?.querySelector(`.module-${state.questionIndex+1}`);if(!stage||!target)return;const origin=object.getBoundingClientRect(),offsetX=event.clientX-origin.left,offsetY=event.clientY-origin.top,pointerId=event.pointerId;object.draggable=false;object.classList.add('dragging');target.classList.add('drop-ready');Object.assign(object.style,{position:'fixed',left:`${origin.left}px`,top:`${origin.top}px`,width:`${origin.width}px`,height:`${origin.height}px`,zIndex:'50',margin:'0'});object.setPointerCapture(pointerId);const move=moveEvent=>{if(moveEvent.pointerId!==pointerId)return;object.style.left=`${moveEvent.clientX-offsetX}px`;object.style.top=`${moveEvent.clientY-offsetY}px`;};const reset=()=>{object.onpointermove=null;object.onpointerup=null;object.onpointercancel=null;object.classList.remove('dragging','returning');target.classList.remove('drop-ready');object.removeAttribute('style');object.draggable=true;};const finish=upEvent=>{if(upEvent.pointerId!==pointerId)return;const targetBox=target.getBoundingClientRect(),accepted=upEvent.clientX>=targetBox.left&&upEvent.clientX<=targetBox.right&&upEvent.clientY>=targetBox.top&&upEvent.clientY<=targetBox.bottom;if(accepted){reset();activateCheckpointModule(stage,CHECKPOINT_DATA[state.questionIndex]);return;}const current=object.getBoundingClientRect();object.classList.add('returning');object.animate([{left:`${current.left}px`,top:`${current.top}px`},{left:`${origin.left}px`,top:`${origin.top}px`}],{duration:280,easing:'ease-out'}).finished.then(reset,reset);};object.onpointermove=move;object.onpointerup=finish;object.onpointercancel=finish;}
document.addEventListener('pointerdown',beginCheckpointPointerDrag);
function activateCheckpointModule(stage,module){if(locked)return;locked=true;audio.sfx('select');stage.querySelector(`.module-${state.questionIndex+1}`).classList.add('activated');stage.querySelector('.checkpoint-object')?.classList.add('installed');transitionId=sceneTimeout(()=>showCheckpointChallenge(stage,module),450);}
function showCheckpointChallenge(stage,module){if(!document.body.contains(stage))return;locked=false;const challenge=document.createElement('section');challenge.className=`checkpoint-challenge challenge-${module.name.toLowerCase()}`;challenge.innerHTML=`<h2>${module.name} SYSTEM</h2><div class="checkpoint-clues"></div><div class="checkpoint-task"></div>`;const clues=challenge.querySelector('.checkpoint-clues');(module.clues||[]).forEach(text=>{const clue=document.createElement('span');clue.textContent=text;clues.append(clue);});const task=challenge.querySelector('.checkpoint-task');if(module.options){const prompt=document.createElement('p');prompt.textContent=module.prompt;const answers=document.createElement('div');answers.className='checkpoint-answers';[...module.options].sort(()=>Math.random()-.5).forEach(option=>{const choice=document.createElement('button');choice.type='button';choice.textContent=option;choice.onclick=()=>answerCheckpointChoice(choice,option,module);answers.append(choice);});task.append(prompt,answers);}else{const form=document.createElement('form');form.className='checkpoint-form';if(module.name==='CAMERA'){const original=document.createElement('p');original.className='checkpoint-original';original.textContent="The security camera isn't working since the second power failure.";const correction=document.createElement('label');correction.textContent='Correct the verb phrase: ';const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=20;input.setAttribute('aria-label','Correct verb phrase');correction.append(input);form.append(original,correction);}else{const sentence=document.createElement('p');module.sentence.forEach((part,index)=>{sentence.append(document.createTextNode(part));if(index<module.answers.length){const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=Math.max(9,module.answers[index].length+1);input.setAttribute('aria-label',`Missing verb form ${index+1}`);sentence.append(input);}});form.append(sentence);}const submit=document.createElement('button');submit.type='submit';submit.textContent='RESTORE SYSTEM';form.append(submit);form.onsubmit=event=>{event.preventDefault();submitCheckpointAnswer(form,module);};task.append(form);}stage.append(challenge);challenge.querySelector('input')?.focus();}
function checkpointAnswerMatches(value,module,index){const accepted=module.acceptedAnswers?.[index]||[module.answers[index]];return accepted.some(answer=>normalizeTypedAnswer(value)===normalizeTypedAnswer(answer));}
function submitCheckpointAnswer(form,module){if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>checkpointAnswerMatches(input.value,module,index));if(correct){completeCheckpointModule(module);return;}inputs.forEach((input,index)=>input.classList.toggle('wrong',!checkpointAnswerMatches(input.value,module,index)));checkpointWrong(inputs,form.querySelector('button'));}
