function showCheckpointComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;const ready=preloadImages([ASSETS.evacuationPoint,ASSETS.interactive.passengerTerminal,ASSETS.interactive.landingLights,ASSETS.interactive.securityGateBase,ASSETS.interactive.securityGateBarrier,ASSETS.interactive.conveyorBox,...Object.values(NIGHTFALL_COLLECTIBLES).map(item=>item.asset)]),version=sceneVersion;const success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>CHECKPOINT RESTORED ✓</h2>';screen.append(success);transitionId=sceneTimeout(()=>completeEnergyStep(10,async()=>{const version=sceneVersion;await ready;if(sceneIsCurrent(version)){state.rescueZoneCompleted=true;showRouteSelection();}}),SHORT_STATUS_DURATION);}
function startHelicopterAmbience(stage){if(helicopterAmbience)return;const track=preparedHelicopterAmbience||new Audio(ASSETS.helicopterAmbience);preparedHelicopterAmbience=null;track.loop=true;track.preload='metadata';track.volume=audio.muted?0:.03;helicopterAmbience=track;const play=()=>{audio.unlock();if(helicopterAmbience===track)track.play().catch(()=>{});};if(audio.enabled)play();else stage.addEventListener('pointerdown',play,{once:true});}
