function showRescueSignal(){const readinessKey='signal';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showRescueSignal);clearScreen();locked=false;state.game=9;state.radioPhase='signal';prepareSection('checkpoint');prepareHelicopterAmbience();const stage=document.createElement('div');stage.className='transmission-game';stage.style.backgroundImage=`url('${ASSETS.transmissionRooftop}')`;stage.style.setProperty('--helicopter-speed','5.8s');stage.innerHTML='<header class="transmission-header"><p>GAME 9 — RESCUE SIGNAL</p><strong>Wait for the helicopter to enter the signal zone, then select it.</strong><span>RADIO CHANNEL RESTORED ✓</span></header><div class="helicopter-flight"><div class="signal-zone zone-wide" aria-hidden="true"></div><button class="moving-helicopter" type="button" aria-label="Transmit rescue signal to helicopter"><img alt="Rescue helicopter"></button></div><section class="transmission-terminal"></section>';stage.querySelector('img').src=ASSETS.interactive.transmissionHelicopter;stage.querySelector('.moving-helicopter').onclick=()=>attemptRescueSignal(stage);screen.append(stage);startHelicopterAmbience(stage);prepareRescueSignal(stage);stage.querySelector('button').focus();}
function prepareRescueSignal(stage){if(!document.body.contains(stage))return;locked=false;stage.dataset.transmissionReady='true';stage.classList.add('transmission-active');const terminal=stage.querySelector('.transmission-terminal');terminal.innerHTML='<strong>SIGNAL READY</strong><p>WAIT UNTIL THE HELICOPTER ENTERS THE SIGNAL ZONE<br>THEN CLICK THE HELICOPTER</p><output>TRANSMISSION WINDOW: 15</output>';startTransmissionCountdown(stage,15);}
function helicopterInsideSignalZone(stage){const helicopter=stage.querySelector('.moving-helicopter')?.getBoundingClientRect(),zone=stage.querySelector('.signal-zone')?.getBoundingClientRect();if(!helicopter||!zone)return false;const center=helicopter.left+helicopter.width/2;return center>=zone.left&&center<=zone.right;}
function startTransmissionCountdown(stage,seconds){clearInterval(transmissionCountdownId);let remaining=seconds;const output=stage.querySelector('.transmission-terminal output');if(output)output.textContent=`TRANSMISSION WINDOW: ${remaining}`;transmissionCountdownId=setInterval(()=>{remaining--;if(output)output.textContent=`TRANSMISSION WINDOW: ${remaining}`;if(remaining<=0){clearInterval(transmissionCountdownId);transmissionCountdownId=0;connectionLost(stage);}},1000);}
