function showEvacuationScene(recent=''){locked=false;updateHud();clearScreen();const stage=document.createElement('div');stage.className='evacuation-game';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<header class="evacuation-header"><p>FINAL EVACUATION</p><strong>FINAL EVACUATION CLEARANCE</strong><span>Complete all four tasks to authorize evacuation.</span><output></output></header><div class="evacuation-stations"></div>';stage.querySelector('output').textContent=`FINAL CLEARANCE: ${state.game12Completed.length*25}%`;const stations=stage.querySelector('.evacuation-stations'),definitions=[['passengers','REGISTER PASSENGERS','passengerTerminal'],['lights','LANDING LIGHTS','landingLights'],['gate','SECURITY GATE','securityGateBase'],['landing','LANDING ZONE','conveyorBox']];definitions.forEach(([id,label,asset])=>{const completed=evacuationStationComplete(id),available=id!=='landing'||evacuationPrerequisitesComplete();const station=document.createElement('button');station.type='button';station.className=`evacuation-station station-${id} ${completed?'completed':''} ${recent===id?'just-completed':''} ${available?'available':'locked'}`;station.disabled=completed||!available;station.setAttribute('aria-label',completed?`${label} ${state.game12Skipped.includes(id)?'resolved via Rescue':'complete'}`:available?label:`${label} locked`);if(id==='gate')station.innerHTML=`<span class="gate-layers"><img class="gate-base" src="${ASSETS.interactive.securityGateBase}" alt=""><img class="gate-barrier" src="${ASSETS.interactive.securityGateBarrier}" alt=""></span>`;else station.innerHTML=`<img src="${ASSETS.interactive[asset]}" alt="">`;if(id==='lights')station.insertAdjacentHTML('beforeend','<span class="light-sequence" aria-hidden="true"><i></i><i></i><i></i></span>');station.insertAdjacentHTML('beforeend',`<span class="station-label">${label}</span><b>${completed?'✓':''}</b><em>${completed?(state.game12Skipped.includes(id)?'RESCUE CLEARANCE':id==='passengers'?'REGISTERED ✓':'COMPLETE ✓'):id==='landing'&&!available?'COMPLETE OTHER SYSTEMS FIRST':'SELECT'}</em>`);station.onclick=()=>openEvacuationStation(id);stations.append(station);});screen.append(stage);}
function openEvacuationStation(id){if(evacuationStationComplete(id))return;if(id==='landing'){if(!evacuationPrerequisitesComplete())return;if(state.game12ObstaclesCleared)showEvacuationTask('landing');else showLandingZoneClearance();return;}showEvacuationTask(id);}
function evacuationTaskShell(instruction){locked=false;state.lives=3;updateHud();clearScreen();const stage=document.createElement('div');stage.className='evacuation-task';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;const panel=document.createElement('section');panel.className='evacuation-task-panel';panel.innerHTML=`<h2>FINAL EVACUATION</h2><strong>${instruction}</strong><div class="evacuation-task-content"></div>`;stage.append(panel);screen.append(stage);return {stage,panel,content:panel.querySelector('.evacuation-task-content')};}
function showEvacuationTask(id){state.game12ActiveStation=id;const task=FINAL_SURVIVAL_DATA[id];if(id==='passengers'){const {content}=evacuationTaskShell('Choose the correct answer.');content.innerHTML='<p class="evacuation-sentence"></p><div class="evacuation-answers"></div>';content.querySelector('p').textContent=task.sentence;task.options.forEach((option,index)=>{const choice=document.createElement('button');choice.type='button';choice.textContent=`${String.fromCharCode(65+index)}) ${option}`;choice.onclick=()=>{if(locked)return;if(option===task.answer){choice.classList.add('correct');completeEvacuationStation(id,'PASSENGER REGISTRATION COMPLETE ✓');}else evacuationWrong([choice]);};content.querySelector('.evacuation-answers').append(choice);});return;}if(id==='lights'){const {content}=evacuationTaskShell('Type the correct verb form.');content.innerHTML='<form class="evacuation-form"><p class="evacuation-sentence"></p><button type="submit">ACTIVATE LIGHTS</button></form>';const form=content.querySelector('form'),sentence=form.querySelector('p'),input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.setAttribute('aria-label','Correct form of circle');sentence.append(document.createTextNode('The helicopter '),input,document.createTextNode(' (circle) above the evacuation zone for several minutes.'));form.onsubmit=event=>{event.preventDefault();if(locked)return;if(normalizeTypedAnswer(input.value)===task.answer)completeEvacuationStation(id,'LANDING LIGHTS ACTIVATED ✓');else evacuationWrong([input]);};input.focus();return;}if(id==='gate'){const {content}=evacuationTaskShell('Find the mistake and correct it.');content.innerHTML='<p class="evacuation-gate-sentence"></p><div class="evacuation-correction"></div>';const sentence=content.querySelector('.evacuation-gate-sentence');task.segments.forEach(segment=>{const choice=document.createElement('button');choice.type='button';choice.textContent=segment;choice.onclick=()=>{if(locked)return;if(segment!==task.wrong){evacuationWrong([choice]);return;}sentence.querySelectorAll('button').forEach(button=>button.disabled=true);choice.classList.add('selected');const correction=content.querySelector('.evacuation-correction');correction.innerHTML='<form><label>Correct the selected part:<input type="text" autocomplete="off" placeholder="Type the correction"></label><button type="submit">UNLOCK GATE</button></form>';const form=correction.querySelector('form'),input=form.querySelector('input');form.onsubmit=event=>{event.preventDefault();if(locked)return;if(normalizeTypedAnswer(input.value)===task.correction){sentence.textContent='The gates will open as soon as the pilot gives the signal.';completeEvacuationStation(id,'SECURITY GATE UNLOCKED ✓');}else evacuationWrong([input]);};input.focus();};sentence.append(choice);});return;}const {content}=evacuationTaskShell('Complete both gaps with the correct verb forms.');content.innerHTML='<form class="evacuation-form evacuation-double"><p class="evacuation-sentence"></p><button type="submit">AUTHORIZE LANDING ZONE</button></form>';const form=content.querySelector('form'),sentence=form.querySelector('p');task.parts.forEach((part,index)=>{sentence.append(document.createTextNode(part));if(index<task.answers.length){const input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.size=index===0?10:24;input.setAttribute('aria-label',`Final clearance verb form ${index+1}`);sentence.append(input);}});form.onsubmit=event=>{event.preventDefault();if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>normalizeTypedAnswer(input.value)===task.answers[index]);if(correct)completeEvacuationStation(id,'LANDING ZONE CLEARED ✓');else evacuationWrong(inputs.filter((input,index)=>normalizeTypedAnswer(input.value)!==task.answers[index]));};form.querySelector('input').focus();}
function evacuationWrong(controls){controls.forEach(control=>{control.classList.remove('wrong');void control.offsetWidth;control.classList.add('wrong');});audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;document.querySelectorAll('.evacuation-task button,.evacuation-task input').forEach(control=>control.disabled=true);transitionId=sceneTimeout(launchEmergencyRescue,750);}}
function completeEvacuationStation(id,message,creditAnswer=true){if(locked||evacuationStationComplete(id))return;locked=true;state.game12Completed.push(id);state.gameProgress=state.game12Completed.length;if(creditAnswer){state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;}else state.game12Skipped.push(id);state.game12ActiveStation=null;audio.sfx('correct');updateHud();document.querySelectorAll('.evacuation-task button,.evacuation-task input').forEach(control=>control.disabled=true);showFeedback(message,'good',SHORT_STATUS_DURATION);transitionId=sceneTimeout(()=>{if(state.game12Completed.length===4)completeEnergyStep(12,()=>{state.evacuationPointCompleted=true;showRouteSelection();});else showEvacuationScene(id);},SHORT_STATUS_DURATION);}
function showLandingZoneClearance(){locked=false;state.game12ActiveStation='landing';clearScreen();const stage=document.createElement('div');stage.className='landing-clear-stage';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<header><h2>CLEAR THE LANDING ZONE</h2><p>Clear the landing zone. Drag all obstacles outside the marked area.</p><output>OBSTACLES: 0/3 CLEARED</output></header><div class="landing-boundary"><span>LANDING ZONE</span></div><div class="landing-obstacles"></div>';const obstacleLayer=stage.querySelector('.landing-obstacles'),starts=[[42,64,-5],[51,72,4],[59,61,-2]];starts.forEach((start,index)=>{const obstacle=document.createElement('img');obstacle.src=ASSETS.interactive.conveyorBox;obstacle.alt=`Landing-zone obstacle ${index+1}`;obstacle.className='landing-obstacle';obstacle.style.left=`${start[0]}%`;obstacle.style.top=`${start[1]}%`;obstacle.style.setProperty('--box-rotation',`${start[2]}deg`);makeLandingObstacleDraggable(obstacle,stage);obstacleLayer.append(obstacle);});screen.append(stage);}
function makeLandingObstacleDraggable(obstacle,stage){let pointerId=null;obstacle.onpointerdown=event=>{if(obstacle.classList.contains('cleared'))return;pointerId=event.pointerId;obstacle.setPointerCapture(pointerId);obstacle.classList.add('dragging');event.preventDefault();};obstacle.onpointermove=event=>{if(event.pointerId!==pointerId)return;const bounds=stage.getBoundingClientRect(),x=Math.max(5,Math.min(95,(event.clientX-bounds.left)/bounds.width*100)),y=Math.max(31,Math.min(94,(event.clientY-bounds.top)/bounds.height*100));obstacle.style.left=`${x}%`;obstacle.style.top=`${y}%`;};const release=event=>{if(!stage.isConnected||event.pointerId!==pointerId)return;pointerId=null;obstacle.classList.remove('dragging');const objectBox=obstacle.getBoundingClientRect(),zoneBox=stage.querySelector('.landing-boundary').getBoundingClientRect(),centerX=objectBox.left+objectBox.width/2,centerY=objectBox.top+objectBox.height/2,inside=centerX>=zoneBox.left&&centerX<=zoneBox.right&&centerY>=zoneBox.top&&centerY<=zoneBox.bottom;if(inside){showFeedback('MOVE THE OBSTACLE OUTSIDE THE LANDING ZONE','info',850);return;}obstacle.classList.add('cleared');obstacle.style.pointerEvents='none';const cleared=stage.querySelectorAll('.landing-obstacle.cleared').length;stage.querySelector('header output').textContent=`OBSTACLES: ${cleared}/3 CLEARED`;if(cleared===3){state.game12ObstaclesCleared=true;locked=true;showFeedback('LANDING ZONE PHYSICALLY CLEAR','good',SHORT_STATUS_DURATION);transitionId=sceneTimeout(()=>showEvacuationTask('landing'),SHORT_STATUS_DURATION);}};obstacle.onpointerup=release;obstacle.onpointercancel=release;}
function showFinalAuthorization(){const readinessKey='evacuation';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showFinalAuthorization);if(state.secrets<5){showNightfallIncomplete();return;}showEvacuationScene();locked=true;const stage=screen.querySelector('.evacuation-game'),message=document.createElement('div');stage.classList.add('final-layout');message.className='final-clearance-message';message.textContent='EVACUATION AUTHORIZED';stage.append(message);transitionId=sceneTimeout(()=>startFinalHelicopterArrival(stage,message),SHORT_STATUS_DURATION);}
function startFinalHelicopterArrival(stage,message){if(!stage.isConnected)return;startHelicopterAmbience(stage);const version=sceneVersion,ready=preloadImages([ASSETS.nightfallLab,ASSETS.nightfallPanel,...Object.values(NIGHTFALL_COLLECTIBLES).map(item=>item.asset)]),helicopter=document.createElement('img');helicopter.className='evacuation-helicopter';helicopter.src=ASSETS.interactive.transmissionHelicopter;helicopter.alt='Rescue helicopter arriving at the evacuation point';stage.append(helicopter);message.classList.add('arrival-hidden');transitionId=sceneTimeout(()=>{message.className='final-clearance-message landed-status';message.textContent='HELICOPTER LANDED ✓';transitionId=sceneTimeout(async()=>{const version=sceneVersion;await ready;if(sceneIsCurrent(version))beginNightfallEndingFlow();},SHORT_STATUS_DURATION);},7200);}
function beginNightfallEndingFlow(){stopHelicopterAmbience();if(state.secrets!==5){showNightfallIncomplete();return;}showNightfallTerminal();}
function showNightfallIncomplete(){const readinessKey='evacuation';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showNightfallIncomplete);showEvacuationScene();locked=false;const notice=document.createElement('div');notice.className='nightfall-missing-message';notice.innerHTML=`<strong>PROJECT NIGHTFALL: ${state.secrets}/5</strong><span>Find the missing evidence to unlock the classified file.</span>`;screen.querySelector('.evacuation-game').append(notice);}
function createNightfallEvidence(){const evidence=document.createElement('div');evidence.className='nightfall-evidence';Object.entries(NIGHTFALL_COLLECTIBLES).forEach(([id,item])=>{const image=document.createElement('img');image.src=item.asset;image.alt=item.name;image.className=`evidence-${id}`;evidence.append(image);});return evidence;}
function showNightfallTerminal(){const readinessKey='nightfall';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showNightfallTerminal);preloadFinalAchievementImages();clearScreen();updateHud();const stage=document.createElement('div');stage.className='nightfall-stage';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;stage.innerHTML='<header class="nightfall-header"><p>PROJECT NIGHTFALL</p><span>CLASSIFIED // LEVEL 5</span><strong>DECRYPT THE CLASSIFIED FILE</strong></header><section class="nightfall-terminal"><form class="nightfall-form"><div class="nightfall-rows"></div><button type="submit">DECRYPT FILE</button><div class="nightfall-unlock-status" aria-live="polite"></div></form></section>';const rows=stage.querySelector('.nightfall-rows');NIGHTFALL_DECRYPTION_DATA.forEach((item,index)=>{const row=document.createElement('label');row.className='nightfall-row';row.dataset.index=index;const sentence=document.createElement('span');sentence.className='nightfall-sentence';const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=Math.max(18,item.answer.length+2);input.setAttribute('aria-label',`Nightfall line ${index+1} missing verb form`);sentence.append(document.createTextNode(item.before),input,document.createTextNode(item.after));row.append(sentence);rows.append(row);});const form=stage.querySelector('.nightfall-form');form.onsubmit=event=>{event.preventDefault();checkNightfallAnswers(stage);};stage.append(createNightfallEvidence());screen.append(stage);form.querySelector('input').focus();}
function checkNightfallAnswers(stage){if(!stage.isConnected||state.nightfallDecryptionCompleted)return;const row=stage.querySelector('.nightfall-row'),input=row.querySelector('input');if(normalizeTypedAnswer(input.value)===NIGHTFALL_DECRYPTION_DATA[0].answer){input.disabled=true;row.classList.remove('wrong');row.classList.add('decrypted');audio.sfx('correct');completeNightfallDecryption(stage);}else{row.classList.remove('wrong');void row.offsetWidth;row.classList.add('wrong');audio.sfx('wrong');input.focus();}}
async function completeNightfallDecryption(stage){stage.querySelector('.nightfall-form>button').disabled=true;state.nightfallDecryptionCompleted=true;awardMasterCollectorIfEligible();stage.classList.add('file-unlocked');const version=sceneVersion;await preloadFinalAchievementImages();if(sceneIsCurrent(version))showNightfallClassifiedFile();}
function showNightfallClassifiedFile(){const readinessKey='nightfall';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showNightfallClassifiedFile);clearScreen();const stage=document.createElement('div');stage.className='nightfall-stage nightfall-reveal';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;const file=document.createElement('section');file.className='classified-reveal';file.innerHTML='<header><p>PROJECT NIGHTFALL</p></header><div class="classified-story"><p>The evidence exposed the hidden Nightfall network that caused the blackout.</p><p>You helped disable it. Power restoration has begun.</p></div>';stage.append(createNightfallEvidence(),file);screen.append(stage);transitionId=sceneTimeout(showFinalMissionResults,READABLE_MESSAGE_DURATION);}
function formatMissionTime(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function awardAchievement(id){if(!state.achievements.includes(id))state.achievements.push(id);}
function awardMasterCollectorIfEligible(){const completeEvidence=Object.keys(NIGHTFALL_COLLECTIBLES).every(id=>state.collectedSecrets.includes(id));if(state.nightfallDecryptionCompleted&&state.secrets===5&&completeEvidence)awardAchievement('masterCollector');}
function evaluateFinalAchievements(){const attempts=state.correctAnswers+state.wrongAnswers,accuracy=attempts?Math.round(state.correctAnswers/attempts*100):100;awardAchievement('explorer');if(accuracy>=80)awardAchievement('grammarMaster');awardMasterCollectorIfEligible();if(state.finalElapsedSeconds<=1800)awardAchievement('speedRunner');if(state.maxStreak>=10)awardAchievement('unstoppable');if(state.emergencyRescueCount===0)awardAchievement('untouchable');}
function showFinalMissionResults(){const readinessKey='results';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,showFinalMissionResults);audio.sfx('complete');clearInterval(timerId);state.finalElapsedSeconds=state.finalElapsedSeconds||Math.max(0,Math.floor((Date.now()-state.startedAt)/1000));evaluateFinalAchievements();hud.classList.add('hidden');clearScreen();const attempts=state.correctAnswers+state.wrongAnswers,accuracy=attempts?Math.round(state.correctAnswers/attempts*100):100,missionTime=formatMissionTime(state.finalElapsedSeconds),evidence=`${state.secrets}/5`,rescue=String(state.emergencyRescueCount),stage=document.createElement('div');stage.className='final-results';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<section class="final-dashboard"><header class="final-results-heading"><h1>MISSION COMPLETE</h1><h2>PROJECT NIGHTFALL REVEALED</h2></header><div class="final-stats" aria-label="Final mission statistics"></div><div class="final-results-lower"><section class="final-achievement-report"><h3>ACHIEVEMENTS UNLOCKED</h3><div class="final-achievements"></div></section><section class="survival-report"><h3>SURVIVAL REPORT</h3><dl></dl></section></div><div class="final-actions"><button type="button">PLAY AGAIN</button><a class="branding-badge" href="https://beeskneeseng.ru" target="_blank" rel="noopener noreferrer"><img src="'+ASSETS.branding+'" alt="Bee\'s Knees English"></a></div></section>';const statValues=[['FINAL SCORE',state.score.toLocaleString()],['TIME',missionTime],['GRAMMAR ACCURACY',`${accuracy}%`],['LIVES REMAINING',String(state.lives)],['SECRETS / EVIDENCE FOUND',evidence],['EMERGENCY RESCUE',rescue]];const stats=stage.querySelector('.final-stats');statValues.forEach(([label,value])=>{const item=document.createElement('p');item.innerHTML='<span></span><strong></strong>';item.querySelector('span').textContent=label;item.querySelector('strong').textContent=value;stats.append(item);});const achievements=stage.querySelector('.final-achievements');FINAL_ACHIEVEMENT_DEFINITIONS.forEach(([id,name,file])=>{const unlocked=state.achievements.includes(id),item=document.createElement('figure');item.className=unlocked?'unlocked':'locked';item.innerHTML=`<img src="${achievementAsset(file)}" alt="${name}"><figcaption>${name}</figcaption>${unlocked?'':'<span>LOCKED</span>'}`;achievements.append(item);});const survivalValues=[['Correct Answers',state.correctAnswers.toLocaleString()],['Accuracy',`${accuracy}%`],['Time',missionTime],['Lives Remaining',String(state.lives)],['Evidence Found',evidence],['Emergency Rescue',rescue],['Final Score',state.score.toLocaleString()]],report=stage.querySelector('.survival-report dl');survivalValues.forEach(([label,value])=>{const term=document.createElement('dt'),description=document.createElement('dd');term.textContent=label;description.textContent=value;report.append(term,description);});stage.querySelector('button').onclick=()=>{audio.sfx('click');state.reset();updateHud();showStart();};screen.append(stage);}
const renderFinalResultsWithExternalBranding=showFinalMissionResults;showFinalMissionResults=function(){renderFinalResultsWithExternalBranding();const stage=screen.querySelector('.final-results'),badge=stage?.querySelector('.branding-badge');if(stage&&badge)stage.append(badge);};
const renderEvacuationScene=showEvacuationScene;
showEvacuationScene=function(recent=''){renderEvacuationScene(recent);const stage=screen.querySelector('.evacuation-game');if(!stage)return;const missing=Object.keys(NIGHTFALL_COLLECTIBLES).filter(id=>!state.collectedSecrets.includes(id));missing.forEach((id,index)=>addNightfallCollectible(stage,id,`nightfall-fallback game12-secret game12-secret-${index+1}`));};
function resumeEvacuationTask(){if(state.game12ActiveStation==='landing'&&!state.game12ObstaclesCleared)showLandingZoneClearance();else showEvacuationTask(state.game12ActiveStation||'passengers');}
audioToggle.addEventListener('click',()=>{if(helicopterAmbience)helicopterAmbience.volume=audio.muted?0:.03;});
document.addEventListener('animationiteration',event=>{if(event.animationName==='helicopterPatrol'&&event.target.classList.contains('moving-helicopter'))event.target.classList.toggle('returning');});
function selectRescueQuestions(){const candidates=RESCUE_QUESTION_POOL.filter(question=>question.id!==previousRescueQuestionId);rescueQuestion=candidates[Math.floor(Math.random()*candidates.length)];previousRescueQuestionId=rescueQuestion.id;}
function launchEmergencyRescue(){const readinessKey='rescue';if(!sectionIsReady(readinessKey))return enterPreparedSection(readinessKey,launchEmergencyRescue);if(rescueContext)return;rescueContext={game:state.game,questionIndex:state.questionIndex,station:state.game12ActiveStation};selectRescueQuestions();renderRescueQuestion();}
function renderRescueQuestion(){clearScreen();locked=false;const stage=document.createElement('div');stage.className='rescue-stage';stage.innerHTML='<section class="rescue-content"><h2>EMERGENCY RESCUE</h2><p class="rescue-instruction">No lives left!<br>Answer one question correctly to continue.</p><p class="rescue-sentence"></p><div class="rescue-answers"></div></section>';stage.querySelector('.rescue-sentence').textContent=rescueQuestion.sentence;rescueQuestion.options.forEach(option=>{const choice=document.createElement('button');choice.type='button';choice.textContent=option;choice.onclick=()=>answerRescue(choice,option);stage.querySelector('.rescue-answers').append(choice);});screen.append(stage);stage.querySelector('button').focus();}
function answerRescue(buttonElement,choice){if(locked)return;locked=true;screen.querySelectorAll('.rescue-answers button').forEach(button=>button.disabled=true);const correct=choice===rescueQuestion.answer;buttonElement.classList.add(correct?'correct':'wrong');audio.sfx(correct?'correct':'wrong');transitionId=sceneTimeout(()=>{if(correct)finishEmergencyRescue();else{selectRescueQuestions();renderRescueQuestion();}},650);}
// Rescue resolves one failed task for progression only; normal answer rewards stay separate.
function finishEmergencyRescue(){if(!rescueContext)return;const failed=rescueContext;rescueContext=null;if(state.game!==failed.game||state.questionIndex!==failed.questionIndex)return;clearScreen();locked=false;state.lives=CONFIG.maxLives;state.emergencyRescueCount++;state.skippedTasks.push(failed);updateHud();switch(failed.game){case 1:nextQuestion();break;case 2:state.gameProgress++;nextQuestion();break;case 3:{const reward=SUPPLY_SEARCH_DATA[failed.questionIndex].reward;if(!state.inventory.includes(reward)&&!state.usedEnergySupplies.includes(reward)&&!state.missedSupplies.includes(reward))state.missedSupplies.push(reward);state.gameProgress++;advanceSupplySearch();break;}case 4:state.questionIndex++;state.gameProgress=state.questionIndex;if(state.questionIndex<SIGNAL_TUNNEL_DATA.length)showTunnelDrive();else showServiceTunnelsComplete();break;case 5:state.gameProgress++;nextErrorDetectorQuestion();break;case 6:state.gameProgress++;nextBridgeWarningQuestion();break;case 7:state.gameProgress++;nextRooftopSignalQuestion();break;case 8:state.gameProgress++;nextTrainTimelineTask();break;case 9:state.gameProgress++;nextEmergencyRadioTransmission();break;case 10:state.gameProgress++;nextCheckpointModule();break;case 12:completeEvacuationStation(failed.station,'TASK SKIPPED — RESCUE CLEARANCE',false);break;}}

function renderAudioPanel(){const panel=document.createElement('section');panel.className='audio-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Audio settings');panel.innerHTML=`<h2>AUDIO</h2><label><span>MUSIC</span><input id="music-volume" type="range" min="0" max="1" step=".05" value="${audio.musicVolume}"><output>${Math.round(audio.musicVolume*100)}%</output></label><label><span>SFX</span><input id="sfx-volume" type="range" min="0" max="1" step=".05" value="${audio.sfxVolume}"><output>${Math.round(audio.sfxVolume*100)}%</output></label><button id="mute-audio" type="button">${audio.muted?'UNMUTE':'MUTE'}</button>`;modalRoot.replaceChildren(panel);const music=panel.querySelector('#music-volume'),sfx=panel.querySelector('#sfx-volume');music.oninput=()=>{audio.setMusicVolume(music.value);music.nextElementSibling.textContent=`${Math.round(music.value*100)}%`;};sfx.oninput=()=>{audio.setSfxVolume(sfx.value);sfx.nextElementSibling.textContent=`${Math.round(sfx.value*100)}%`;};panel.querySelector('#mute-audio').onclick=event=>{event.stopPropagation();event.currentTarget.textContent=audio.toggleMute()?'UNMUTE':'MUTE';updateAudioIcon();};panel.onclick=event=>event.stopPropagation();return panel;}
function toggleAudioPanel(forceOpen=false){if(state.energy===0||modalRoot.querySelector('.energy-recovery')){showFeedback('NO ENERGY! Choose a supply from your backpack.');return;}const open=modalRoot.firstElementChild;if(open&&!forceOpen){closeAudioPanel();return;}if(!open)renderAudioPanel();audioToggle.setAttribute('aria-expanded','true');}
function closeAudioPanel(){modalRoot.replaceChildren();audioToggle.setAttribute('aria-expanded','false');document.querySelector('#backpack').setAttribute('aria-expanded','false');}
function showEnergyRecovery(){locked=true;const recoveryItems=[['Water Bottle',ASSETS.items.waterBottle],['Chocolate Bar',ASSETS.items.chocolateBar],['First Aid Kit',ASSETS.items.firstAidKit],['Batteries',ASSETS.items.batteries]].filter(([name])=>state.inventory.includes(name)&&!state.usedEnergySupplies.includes(name));const panel=document.createElement('section');panel.className='energy-recovery';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Energy depleted');panel.innerHTML='<h2>NO ENERGY!</h2><p>Open your backpack and choose a supply.</p><div class="energy-supplies"></div><output aria-live="polite"></output>';const supplies=panel.querySelector('.energy-supplies');recoveryItems.forEach(([name,asset])=>{const use=document.createElement('button');use.type='button';use.innerHTML=`<img src="${asset}" alt=""><span>${name.toUpperCase()}</span>`;use.onclick=event=>{event.stopPropagation();useEnergySupply(name,use);};supplies.append(use);});if(!recoveryItems.length&&state.missedSupplies.length){const name=state.missedSupplies.find(item=>!state.inventory.includes(item)&&!state.usedEnergySupplies.includes(item));if(name){const recover=document.createElement('button');recover.type='button';recover.textContent=`RECOVER MISSED SUPPLY: ${name.toUpperCase()}`;recover.onclick=()=>{if(!recover.isConnected||recover.disabled||state.inventory.includes(name)||state.usedEnergySupplies.includes(name))return;recover.disabled=true;state.missedSupplies=state.missedSupplies.filter(item=>item!==name);state.inventory.push(name);audio.sfx('itemPickup');updateHud();showEnergyRecovery();};supplies.append(recover);}}if(!supplies.children.length){const empty=document.createElement('strong');empty.className='energy-empty';empty.textContent='NO ENERGY SUPPLIES AVAILABLE';supplies.append(empty);}panel.onclick=event=>event.stopPropagation();modalRoot.replaceChildren(panel);document.querySelector('#backpack').setAttribute('aria-expanded','true');panel.querySelector('button')?.focus();}
function useEnergySupply(name,buttonElement){const itemIndex=state.inventory.indexOf(name);if(buttonElement.disabled||itemIndex<0||state.usedEnergySupplies.includes(name))return;const panel=buttonElement.closest('.energy-recovery');panel.querySelectorAll('button').forEach(button=>button.disabled=true);buttonElement.classList.add('selected');state.inventory.splice(itemIndex,1);state.usedEnergySupplies.push(name);state.energy=CONFIG.maxEnergy;updateHud();audio.sfx('itemPickup');panel.classList.add('restored');panel.querySelector('output').textContent='ENERGY RESTORED — 100%';const continuation=energyRecoveryContinuation;energyRecoveryContinuation=null;transitionId=sceneTimeout(()=>{modalRoot.replaceChildren();document.querySelector('#backpack').setAttribute('aria-expanded','false');locked=false;if(continuation)continuation();},2000);}
