function debugReadinessSections(){
  const name=DEV_TARGET||'';
  if(/route|routes/.test(name))return ['route','evacuation'];
  if(/nightfall|ending|final|mission-complete|reveal/.test(name))return ['nightfall','results','home','phone'];
  if(/game12|evacuation|fallback-game12/.test(name))return ['evacuation','signal'];
  if(/game10|checkpoint/.test(name))return ['checkpoint'];
  if(/signal|helicopter/.test(name))return ['signal','checkpoint'];
  if(/game9|radio/.test(name))return ['game9'];
  if(/game8|train/.test(name))return ['game8','game9'];
  if(/game7|rooftop/.test(name))return ['game7','game8'];
  if(/game6|bridge/.test(name))return ['game6'];
  if(/city/.test(name))return ['game5'];
  if(/tunnel/.test(name))return ['game4'];
  if(/game3|supply/.test(name))return ['game3'];
  if(/game2|street/.test(name))return ['game2'];
  if(/rules/.test(name))return ['how'];
  return ['home','phone','rescue'];
}
async function initialLoad(){
  const bar=document.querySelector('#load-bar'),value=document.querySelector('#load-value');
  const clickReady=audio.preloadSfx(['click']);let timeout;
  const [startReady]=await Promise.all([prepareSection('start',{priority:true,decode:true}),Promise.race([clickReady,new Promise(resolve=>{timeout=setTimeout(resolve,1600);})])]);clearTimeout(timeout);
  if(!startReady){setTimeout(initialLoad,1000);return;}
  bar.style.width='100%';value.textContent='100%';
  const debug=DEV_REQUEST&&LOCAL_DEV_HOSTS.has(location.hostname);
  if(debug){await prepareSection('phone',{priority:true,decode:true});await Promise.all(debugReadinessSections().map(key=>prepareSection(key,{priority:true,decode:true})));hud.querySelector(':scope > img').src=ASSETS.hud;}
  document.querySelector('#loading').classList.add('hidden');updateAudioIcon();
  if(!startMilestoneUiReview()&&!startFinalResultsPreviewDevMode()&&!startNightfallEvidencePreviewDevMode()&&!startClassifiedRevealDevMode()&&!startNarrativeDebugMode()&&!startSecretFallbackDevMode()&&!startGameThreeIntroDevMode()&&!startNightfallDevMode()&&!startDevMode())showStart();
}
